(()=>{'use strict';
const api=()=>window.CAGE_BACKEND,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let records=[],cohorts=[];
const dialog=document.createElement('dialog');dialog.className='experience-dialog';document.body.append(dialog);
function modal(title,body){dialog.innerHTML=`<header><h2>${esc(title)}</h2><button type="button" data-partner-close aria-label="Close">×</button></header>${body}<p id="partner-error" class="field-error" role="status"></p>`;if(!dialog.open)dialog.showModal();}
const field=(name,label,value='',type='text',required=false)=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} maxlength="300"></label>`;
async function render(root){if(api()?.moduleLevel('training')!=='edit'){root.textContent='Academy edit access is required for the partner register.';return;}root.innerHTML='<p>Loading SH Aviation registrations…</p>';try{const [rows,training]=await Promise.all([api().hubCall('hub_partner_list'),api().loadTraining()]);if(!root.isConnected)return;records=rows;cohorts=training.cohorts.filter(c=>training.courses.some(t=>t.id===c.course_id&&t.category==='RPL')&&!['Completed','Cancelled'].includes(c.status));root.innerHTML=`<section class="partner-panel"><h2>RPL · SH Aviation intake</h2><p>Register learners supplied by SH Aviation here. CAGE applicants continue through Applications & calls. This route records the source and bypasses the application form; it does not mark fees paid or documents verified.</p><button class="primary-button" type="button" data-partner-new>Add partner learner</button><label>Find learner<input id="partner-search" type="search" placeholder="Name, email or partner reference"></label><div id="partner-rows"></div></section>`;draw();root.querySelector('#partner-search').oninput=draw;}catch(e){root.textContent=e.message;}}
function draw(){const box=document.getElementById('partner-rows');if(!box)return;const q=document.getElementById('partner-search').value.toLowerCase();box.innerHTML=records.filter(p=>`${p.full_name} ${p.email} ${p.reference}`.toLowerCase().includes(q)).map(p=>`<article class="partner-row"><strong>${esc(p.full_name)}</strong><p>SH Aviation · ${esc(p.status)} · ${esc(cohorts.find(c=>c.id===p.cohort_id)?.name||'Cohort on record')}</p><p>${esc(p.email||'')} ${esc(p.phone||'')} ${p.reference?'· '+esc(p.reference):''}</p>${p.status==='Invited'?`<p>Details link expires ${esc(new Date(p.expires_at).toLocaleDateString())}. If the link is lost, revoke this invitation and create another.</p>`:''}<div class="partner-actions">${!['Enrolled','Revoked'].includes(p.status)?`<button type="button" data-partner-review="${p.id}">Review & enrol</button><button type="button" data-partner-revoke="${p.id}">Revoke</button>`:''}</div></article>`).join('')||'<p>No matching partner registrations.</p>';}
function create(){if(!cohorts.length){showToast('Create an active RPL cohort first.');return;}modal('Add SH Aviation learner',`<form id="partner-create"><label>RPL cohort<select name="cohort" required>${cohorts.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label>${field('full_name','Full name','','text',true)}${field('email','Email','','email')}${field('phone','Phone')}${field('reference','SH Aviation list / reference')}<label>Internal notes<textarea name="notes" maxlength="3000"></textarea></label><p>A private, single-use details link will be generated, valid for 14 days. Copy and share it with this learner. You may also verify and enter details from SH Aviation’s list yourself.</p><button class="primary-button">Create registration</button></form>`);}
function review(id){const p=records.find(r=>r.id===id);if(!p)return;modal('Verify SH Aviation learner',`<form id="partner-enrol" data-id="${p.id}"><p>Source: SH Aviation · RPL</p>${field('full_name','Full name',p.full_name,'text',true)}${field('email','Email',p.email,'email')}${field('phone','Phone',p.phone,'tel',true)}${field('date_of_birth','Date of birth',p.date_of_birth,'date')}<p>${p.consented_at?'Learner submitted their details and consent.':'Staff entry from the SH Aviation list. Confirm you are authorised to register this person.'}</p><label><input type="checkbox" name="confirmed" required> I have checked the partner list and learner details and am authorised to register this learner.</label><p>This creates their Academy learner record. Required document checks, fees and certification requirements still apply.</p><button class="primary-button">Confirm enrolment</button></form>`);}
async function reload(){const root=document.getElementById('academy-content');if(document.querySelector('[data-academy="tab"][data-id="partner"][aria-selected="true"]'))await render(root);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-partner-close'))dialog.close();if(b.hasAttribute('data-partner-new'))create();if(b.dataset.partnerReview)review(b.dataset.partnerReview);if(b.dataset.partnerRevoke)modal('Revoke partner registration',`<p>The learner’s details link will stop working. No enrolled learner is deleted.</p><button type="button" data-partner-confirm-revoke="${esc(b.dataset.partnerRevoke)}">Confirm revoke</button>`);if(b.dataset.partnerConfirmRevoke){b.disabled=true;api().hubCall('hub_partner_revoke',{intake_key:b.dataset.partnerConfirmRevoke}).then(()=>{dialog.close();reload();}).catch(e=>{document.getElementById('partner-error').textContent=e.message;b.disabled=false;});}if(b.id==='partner-copy'){navigator.clipboard.writeText(document.getElementById('partner-link').value).then(()=>{b.textContent='Copied';}).catch(()=>{document.getElementById('partner-link').select();});}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['partner-create','partner-enrol'].includes(f.id))return;e.preventDefault();const b=e.submitter;b.disabled=true;try{const details=Object.fromEntries(new FormData(f));if(f.id==='partner-create'){const result=await api().hubCall('hub_partner_create',{cohort_key:details.cohort,details});const link=new URL('/partner-register.html',location.origin);link.hash=result.token;modal('Private learner registration link',`<p>Share this link only with the intended learner. It can be used once and expires in 14 days.</p><input id="partner-link" class="partner-link" readonly value="${esc(link.href)}" aria-label="Private registration link"><button id="partner-copy" type="button">Copy link</button><p>No message has been sent automatically.</p>`);}else{details.confirmed=true;await api().hubCall('hub_partner_enrol',{intake_key:f.dataset.id,details});dialog.close();showToast('SH Aviation learner enrolled.');}await reload();}catch(err){document.getElementById('partner-error').textContent=err.message;}finally{b.disabled=false;}});
window.CAGE_PARTNER={render};window.addEventListener('cage:access-closed',()=>{records=[];dialog.close();});
})();
